import{_ as t,c as a,o as n,ag as r}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Profinet-kommunikation","description":"","frontmatter":{},"headers":[],"relativePath":"06-kommunikation/profinet.md","filePath":"06-kommunikation/profinet.md","lastUpdated":1768462574000}'),i={name:"06-kommunikation/profinet.md"};function o(l,e,s,d,p,g){return n(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="profinet-kommunikation" tabindex="-1">Profinet-kommunikation <a class="header-anchor" href="#profinet-kommunikation" aria-label="Permalink to &quot;Profinet-kommunikation&quot;">​</a></h1><p><strong>Profinet</strong> (Process Field Net) är Siemens industriella Ethernet-standard för realtidskommunikation mellan PLC, HMI, I/O-moduler och fältenheter som frekvensomriktare. Det är ryggraden i moderna TIA Portal-system.</p><h2 id="vad-ar-profinet" tabindex="-1">Vad är Profinet? <a class="header-anchor" href="#vad-ar-profinet" aria-label="Permalink to &quot;Vad är Profinet?&quot;">​</a></h2><p>Profinet är en <strong>industriell Ethernet-protokoll</strong> baserad på standard TCP/IP som tillåter:</p><ul><li>⚡ <strong>Realtidskommunikation</strong> - deterministisk dataöverföring</li><li>🔌 <strong>Plug &amp; Play</strong> - automatisk enhetsidentifiering</li><li>🌐 <strong>Ethernet-baserad</strong> - använder standard nätverkskablar (Cat5e/Cat6)</li><li>🔧 <strong>Flexibel topologi</strong> - linjär, stjärna eller ring</li></ul><h3 id="profinet-vs-andra-protokoll" tabindex="-1">Profinet vs andra protokoll <a class="header-anchor" href="#profinet-vs-andra-protokoll" aria-label="Permalink to &quot;Profinet vs andra protokoll&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Protokoll</th><th>Hastighet</th><th>Användning</th><th>TIA Portal-stöd</th></tr></thead><tbody><tr><td><strong>Profinet</strong></td><td>100 Mbit/s</td><td>Moderna system, realtid</td><td>✅ Primärt</td></tr><tr><td><strong>Profibus DP</strong></td><td>12 Mbit/s</td><td>Äldre system, fältbuss</td><td>⚠️ Legacy</td></tr><tr><td><strong>Ethernet/IP</strong></td><td>100 Mbit/s</td><td>Rockwell/Allen-Bradley</td><td>❌ Ej native</td></tr><tr><td><strong>Modbus TCP</strong></td><td>100 Mbit/s</td><td>Öppen standard</td><td>✅ Via FB</td></tr></tbody></table><h2 id="profinet-komponenter" tabindex="-1">Profinet-komponenter <a class="header-anchor" href="#profinet-komponenter" aria-label="Permalink to &quot;Profinet-komponenter&quot;">​</a></h2><h3 id="_1-io-controller-plc" tabindex="-1">1. IO Controller (PLC) <a class="header-anchor" href="#_1-io-controller-plc" aria-label="Permalink to &quot;1. IO Controller (PLC)&quot;">​</a></h3><p>Master som <strong>styr</strong> kommunikationen - din S7-1200/1500.</p><h3 id="_2-io-device" tabindex="-1">2. IO Device <a class="header-anchor" href="#_2-io-device" aria-label="Permalink to &quot;2. IO Device&quot;">​</a></h3><p>Slav-enheter som <strong>svarar</strong> på IO Controller:</p><ul><li>I/O-moduler (ET 200SP, ET 200MP)</li><li>Frekvensomriktare (Sinamics G120)</li><li>Fjärr-I/O</li><li>Tredjepartsenhe ter</li></ul><h3 id="_3-io-supervisor" tabindex="-1">3. IO Supervisor <a class="header-anchor" href="#_3-io-supervisor" aria-label="Permalink to &quot;3. IO Supervisor&quot;">​</a></h3><p>Enheter för <strong>diagnostik och konfiguration</strong> (ex: engineering station, HMI).</p><h2 id="profinet-adressering" tabindex="-1">Profinet-adressering <a class="header-anchor" href="#profinet-adressering" aria-label="Permalink to &quot;Profinet-adressering&quot;">​</a></h2><h3 id="ip-adresser" tabindex="-1">IP-adresser <a class="header-anchor" href="#ip-adresser" aria-label="Permalink to &quot;IP-adresser&quot;">​</a></h3><p>Varje Profinet-enhet behöver en <strong>IP-adress</strong> på samma subnät.</p><p><strong>Exempel:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLC (S7-1200):           192.168.0.1 / 255.255.255.0</span></span>
<span class="line"><span>HMI (KTP700):            192.168.0.10 / 255.255.255.0</span></span>
<span class="line"><span>Frekvensomriktare:       192.168.0.20 / 255.255.255.0</span></span>
<span class="line"><span>ET 200SP I/O:            192.168.0.30 / 255.255.255.0</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Subnät</p><p>Använd privat subnät (192.168.x.x eller 10.0.x.x) och <strong>planera IP-adresser</strong> från början. Dokumentera alla adresser!</p></div><h3 id="device-name" tabindex="-1">Device Name <a class="header-anchor" href="#device-name" aria-label="Permalink to &quot;Device Name&quot;">​</a></h3><p>Varje enhet har också ett <strong>unikt enhetsnamn</strong> (ex: <code>plc-main-01</code>, <code>drive-m01</code>).</p><p><strong>Tilldela device name:</strong></p><ol><li>I TIA Portal, markera enheten i <strong>Device view</strong></li><li><strong>Properties</strong> → <strong>Profinet interface</strong></li><li><strong>Device name:</strong> Skriv unikt namn (ingen mellanslag)</li></ol><h2 id="skapa-profinet-natverk-i-tia-portal" tabindex="-1">Skapa Profinet-nätverk i TIA Portal <a class="header-anchor" href="#skapa-profinet-natverk-i-tia-portal" aria-label="Permalink to &quot;Skapa Profinet-nätverk i TIA Portal&quot;">​</a></h2><h3 id="steg-1-konfigurera-plc-ns-profinet-interface" tabindex="-1">Steg 1: Konfigurera PLC:ns Profinet-interface <a class="header-anchor" href="#steg-1-konfigurera-plc-ns-profinet-interface" aria-label="Permalink to &quot;Steg 1: Konfigurera PLC:ns Profinet-interface&quot;">​</a></h3><ol><li>Markera din PLC i <strong>Project tree</strong></li><li>Öppna <strong>Device configuration</strong></li><li>Markera <strong>Profinet interface</strong> (grönt kort)</li><li>I <strong>Properties</strong>: <ul><li><strong>IP address:</strong> 192.168.0.1</li><li><strong>Subnet mask:</strong> 255.255.255.0</li><li><strong>Device name:</strong> <code>plc-main-01</code></li></ul></li></ol><h3 id="steg-2-lagg-till-profinet-enheter" tabindex="-1">Steg 2: Lägg till Profinet-enheter <a class="header-anchor" href="#steg-2-lagg-till-profinet-enheter" aria-label="Permalink to &quot;Steg 2: Lägg till Profinet-enheter&quot;">​</a></h3><p><strong>Exempel: Lägg till ET 200SP I/O-modul</strong></p><ol><li>Öppna <strong>Hardware catalog</strong> (högerkant i Device view)</li><li>Sök efter din modul (ex: <code>ET 200SP</code>)</li><li>Dra modulen till <strong>Network view</strong></li><li>Konfigurera modulen: <ul><li>IP-adress: 192.168.0.30</li><li>Device name: <code>io-station-01</code></li></ul></li></ol><h3 id="steg-3-skapa-profinet-anslutning" tabindex="-1">Steg 3: Skapa Profinet-anslutning <a class="header-anchor" href="#steg-3-skapa-profinet-anslutning" aria-label="Permalink to &quot;Steg 3: Skapa Profinet-anslutning&quot;">​</a></h3><ol><li>I <strong>Network view</strong>, dra en linje från PLC:ns Profinet-port till I/O-modulens port</li><li>TIA Portal skapar automatiskt en <strong>Profinet-subnet</strong> (grön linje)</li><li>Alternativt: Högerklicka PLC → <strong>Assign device</strong> → Välj enhet</li></ol><h3 id="steg-4-konfigurera-i-o-adresser" tabindex="-1">Steg 4: Konfigurera I/O-adresser <a class="header-anchor" href="#steg-4-konfigurera-i-o-adresser" aria-label="Permalink to &quot;Steg 4: Konfigurera I/O-adresser&quot;">​</a></h3><p>När Profinet-enheten är ansluten, visas dess I/O i <strong>Device view</strong>.</p><p><strong>Exempel: ET 200SP med 8DI + 8DQ-modul</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital inputs:  %I64.0 - %I64.7</span></span>
<span class="line"><span>Digital outputs: %Q64.0 - %Q64.7</span></span></code></pre></div><p>Du kan ändra startadress genom att högerklicka modulen → <strong>Properties</strong> → <strong>I/O addresses</strong>.</p><h2 id="diagnostik-och-felsokning" tabindex="-1">Diagnostik och felsökning <a class="header-anchor" href="#diagnostik-och-felsokning" aria-label="Permalink to &quot;Diagnostik och felsökning&quot;">​</a></h2><h3 id="online-diagnostik" tabindex="-1">Online-diagnostik <a class="header-anchor" href="#online-diagnostik" aria-label="Permalink to &quot;Online-diagnostik&quot;">​</a></h3><ol><li>Koppla PLC till datorn (Ethernet)</li><li>Gå <strong>Online</strong> i TIA Portal</li><li>Öppna <strong>Online &amp; Diagnostics</strong></li><li>Välj <strong>Accessible devices</strong> för att se alla Profinet-enheter</li></ol><h3 id="vanliga-problem" tabindex="-1">Vanliga problem <a class="header-anchor" href="#vanliga-problem" aria-label="Permalink to &quot;Vanliga problem&quot;">​</a></h3><h4 id="problem-1-device-not-found" tabindex="-1">Problem 1: &quot;Device not found&quot; <a class="header-anchor" href="#problem-1-device-not-found" aria-label="Permalink to &quot;Problem 1: &quot;Device not found&quot;&quot;">​</a></h4><p><strong>Checklista:</strong></p><ul><li>✅ Är kabeln inkopplad korrekt? (grön LED på port)</li><li>✅ Är IP-adresserna på samma subnät?</li><li>✅ Har du tilldelat ett device name till enheten?</li><li>✅ Blockerar brandväggen kommunikationen?</li></ul><p><strong>Lösning:</strong> Använd <strong>Assign device name</strong> i TIA Portal:</p><ol><li>Online &amp; Diagnostics → <strong>Assign device name</strong></li><li>Välj enhet från listan (MAC-adress visas)</li><li>Tilldela device name</li></ol><h4 id="problem-2-communication-error" tabindex="-1">Problem 2: &quot;Communication error&quot; <a class="header-anchor" href="#problem-2-communication-error" aria-label="Permalink to &quot;Problem 2: &quot;Communication error&quot;&quot;">​</a></h4><p><strong>Orsaker:</strong></p><ul><li>Nätverkskabel skadad eller för lång (&gt;100m utan switch)</li><li>IP-konflikt (två enheter med samma IP)</li><li>Fel GSDML-fil (för tredjepartsutrustning)</li></ul><p><strong>Lösning:</strong></p><ul><li>Testa kabel med <strong>ping</strong> från datorn</li><li>Scanna nätverket för IP-konflikter</li><li>Ladda ner senaste GSDML-fil från tillverkaren</li></ul><h4 id="problem-3-intermittent-kommunikation" tabindex="-1">Problem 3: Intermittent kommunikation <a class="header-anchor" href="#problem-3-intermittent-kommunikation" aria-label="Permalink to &quot;Problem 3: Intermittent kommunikation&quot;">​</a></h4><p><strong>Orsaker:</strong></p><ul><li>Dålig kabel eller connector</li><li>EMI-störning (kablar nära kraftkablar)</li><li>För hög processorbelastning på PLC</li></ul><p><strong>Lösning:</strong></p><ul><li>Använd skärmad Cat5e/Cat6-kabel</li><li>Separera Profinet-kablar från kraftkablar (&gt;20 cm)</li><li>Optimera PLC-program (undvik längre loopar i OB1)</li></ul><h2 id="profinet-irt-isochronous-real-time" tabindex="-1">Profinet IRT (Isochronous Real-Time) <a class="header-anchor" href="#profinet-irt-isochronous-real-time" aria-label="Permalink to &quot;Profinet IRT (Isochronous Real-Time)&quot;">​</a></h2><p>För <strong>mycket snabba applikationer</strong> (motion control, synkronisering), använd <strong>Profinet IRT</strong>.</p><h3 id="rt-vs-irt" tabindex="-1">RT vs IRT <a class="header-anchor" href="#rt-vs-irt" aria-label="Permalink to &quot;RT vs IRT&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Läge</th><th>Cykeltid</th><th>Jitter</th><th>Användning</th></tr></thead><tbody><tr><td><strong>RT (Real-Time)</strong></td><td>~1-10 ms</td><td>±1 ms</td><td>Standard I/O, drives</td></tr><tr><td><strong>IRT (Isochronous)</strong></td><td>~250 µs - 4 ms</td><td>&lt;1 µs</td><td>Motion control, synkronisering</td></tr></tbody></table><p><strong>Aktivera IRT:</strong></p><ol><li>Device view → Profinet interface → Properties</li><li><strong>Real-time settings</strong> → <strong>IRT</strong></li><li>Ställ in <strong>Send clock:</strong> (ex: 1 ms)</li></ol><div class="warning custom-block"><p class="custom-block-title">IRT-krav</p><p>IRT kräver <strong>S7-1500</strong> (inte 1200) och speciella <strong>IRT-capable</strong> switches. Använd endast när extremt hög precision krävs.</p></div><h2 id="profinet-topology" tabindex="-1">Profinet Topology <a class="header-anchor" href="#profinet-topology" aria-label="Permalink to &quot;Profinet Topology&quot;">​</a></h2><h3 id="linjar-topologi" tabindex="-1">Linjär topologi <a class="header-anchor" href="#linjar-topologi" aria-label="Permalink to &quot;Linjär topologi&quot;">​</a></h3><p>Enheter kopplade i serie (daisy-chain).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PLC] ─── [Switch] ─── [I/O] ─── [Drive] ─── [HMI]</span></span></code></pre></div><p><strong>Fördelar:</strong></p><ul><li>✅ Enkel kabeldragning</li><li>✅ Mindre kablar</li></ul><p><strong>Nackdelar:</strong></p><ul><li>❌ En enhet som fallerar kan bryta kedjan</li><li>❌ Svårare felsökning</li></ul><h3 id="stjarntopologi" tabindex="-1">Stjärntopologi <a class="header-anchor" href="#stjarntopologi" aria-label="Permalink to &quot;Stjärntopologi&quot;">​</a></h3><p>Alla enheter ansluter till central switch.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         [Switch]</span></span>
<span class="line"><span>        /  |  |  \\</span></span>
<span class="line"><span>      /    |  |    \\</span></span>
<span class="line"><span>  [PLC] [I/O] [Drive] [HMI]</span></span></code></pre></div><p><strong>Fördelar:</strong></p><ul><li>✅ Enkel felsökning</li><li>✅ Redundans (en enhet påverkar inte andra)</li></ul><p><strong>Nackdelar:</strong></p><ul><li>❌ Mer kabeldragning</li><li>❌ Kräver industrial switch</li></ul><h3 id="ring-topologi-mrp" tabindex="-1">Ring-topologi (MRP) <a class="header-anchor" href="#ring-topologi-mrp" aria-label="Permalink to &quot;Ring-topologi (MRP)&quot;">​</a></h3><p>Profinet MRP (Media Redundancy Protocol) ger redundans.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   [PLC]</span></span>
<span class="line"><span>   /    \\</span></span>
<span class="line"><span>[I/O]   [Drive]</span></span>
<span class="line"><span>   \\    /</span></span>
<span class="line"><span>  [Switch]</span></span></code></pre></div><p><strong>Fördelar:</strong></p><ul><li>✅ Hög tillgänglighet (auto-recovery vid kabelbrott)</li><li>✅ &lt;200 ms återställningstid</li></ul><p><strong>Nackdelar:</strong></p><ul><li>❌ Kräver MRP-capable enheter</li><li>❌ Mer komplex konfiguration</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Rekommendationer</p><ol><li><strong>Planera IP-adresser:</strong> Dokumentera alla enheter i Excel/tabell</li><li><strong>Använd device names:</strong> Förenklar felsökning</li><li><strong>Skärmade kablar:</strong> Cat5e/Cat6 med skärmning för industrimiljö</li><li><strong>Industrial switches:</strong> Använd <strong>Scalance X-series</strong> för stora nätverk</li><li><strong>Diagnostik:</strong> Aktivera Profinet-diagnostik i alla enheter</li><li><strong>Firmware:</strong> Håll all firmware uppdaterad</li><li><strong>Dokumentera topologi:</strong> Rita nätverkskarta över fysisk layout</li><li><strong>Redundans:</strong> Använd MRP-ring för kritiska system</li></ol></div><h2 id="praktiskt-exempel-profinet-system" tabindex="-1">Praktiskt exempel: Profinet-system <a class="header-anchor" href="#praktiskt-exempel-profinet-system" aria-label="Permalink to &quot;Praktiskt exempel: Profinet-system&quot;">​</a></h2><h3 id="system-med-plc-hmi-drive" tabindex="-1">System med PLC + HMI + Drive <a class="header-anchor" href="#system-med-plc-hmi-drive" aria-label="Permalink to &quot;System med PLC + HMI + Drive&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enhet                 IP-adress         Device name        Funktion</span></span>
<span class="line"><span>-----------------------------------------------------------------------------</span></span>
<span class="line"><span>S7-1200 PLC           192.168.0.1       plc-main          IO Controller</span></span>
<span class="line"><span>KTP700 HMI            192.168.0.10      hmi-panel         Operatörspanel</span></span>
<span class="line"><span>Sinamics G120         192.168.0.20      drive-m01         Motor 1</span></span>
<span class="line"><span>ET 200SP I/O          192.168.0.30      io-remote-01      Fjärr-I/O</span></span></code></pre></div><p><strong>TIA Portal-konfiguration:</strong></p><ol><li>Konfigurera PLC Profinet-interface (192.168.0.1)</li><li>Lägg till HMI med Profinet-anslutning</li><li>Lägg till G120 från Hardware catalog (installera GSDML först)</li><li>Lägg till ET 200SP och montera I/O-moduler</li><li>Skapa kopplingar i Network view</li><li>Tilldela device names till alla enheter</li><li>Ladda ner till PLC och testa kommunikation</li></ol><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/document/19289930/profinet-system-description" target="_blank" rel="noreferrer">Siemens: Profinet System Description (PDF)</a></li><li><a href="https://www.youtube.com/watch?v=lQG8qlnPJY4" target="_blank" rel="noreferrer">Video: Profinet Basics and Configuration</a></li><li><a href="https://www.youtube.com/watch?v=A4eMVuOpNJ0" target="_blank" rel="noreferrer">Video: Profinet Topology Options</a></li><li><a href="./hmi-kommunikation.html">Nästa: HMI-kommunikation →</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./../03-konfiguration/frekvensomriktare-profinet.html">Konfiguration av Profinet-enheter</a></li><li><a href="./frekvensomriktare-komm.html">Frekvensomriktare-kommunikation</a></li><li><a href="./../05-taggar/koppling-plc-hmi.html">HMI-koppling till PLC</a></li></ul>`,98)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
